/* 关节驱动板 DRV-JOINT B 版 示例固件：经 SPI1 读编码器接口芯片 WQ-ENCIF。第 100 轮。
 * 每 1 ms：读计数和状态 → 算角度、转速、圈数；Z 相锁存后给出绝对角度；芯片报错时记数并清除；
 * 芯片不响应（ID 不对）时停在“芯片缺失”，每 100 ms 重试一次。
 * 板上没有调试串口：结果放在内存里的遥测区 tlm，调试器经 SWD 看（仿真里由 Renode 读内存）。
 * 示例固件，仿真验证；芯片未流片、B 版不投产。 */
#include <stdint.h>
#include "encif.h"
#include "regs.h"

#define CPR 10000          /* 2500 线编码器 ×4（第 88 轮的示例编码器） */
#define WIN_MS 10          /* 转速取 10 ms 窗口 */
#define RETRY_MS 100

enum { ST_BOOT = 0, ST_RUN = 1, ST_MISSING = 2 };

typedef struct {
    uint32_t magic;        /* "TLM1" */
    uint32_t state;        /* 0 启动、1 运行、2 芯片缺失 */
    uint32_t id;           /* 读到的芯片 ID */
    uint32_t ctrl;         /* 回读的控制寄存器 */
    uint32_t tick_ms;
    int32_t cnt;           /* 芯片计数（补码，可为负） */
    int32_t turns;         /* 开机以来的圈数（向下取整） */
    int32_t angle_cnt;     /* 本圈内位置 0..CPR-1（相对开机位置） */
    int32_t rpm_x10;       /* 转速 ×10 */
    int32_t idx;           /* Z 相锁存的计数 */
    uint32_t idx_valid;
    int32_t abs_cnt;       /* 绝对位置 0..CPR-1（相对 Z 相）；未见 Z 时 -1 */
    uint32_t err_count;    /* 芯片报的错误（A/B 同跳）次数 */
    uint32_t status;       /* 最近一次状态寄存器 */
    uint32_t frames;       /* SPI 帧数 */
    uint32_t retries;      /* 芯片缺失时的重试次数 */
} telemetry_t;

volatile telemetry_t tlm;
static volatile uint32_t ticks;
static int32_t hist[WIN_MS];

void SysTick_Handler(void) { ticks++; }

static int32_t mod_cpr(int32_t x) { int32_t r = x % CPR; return r < 0 ? r + CPR : r; }
static int32_t div_cpr(int32_t x) { return (x - mod_cpr(x)) / CPR; }

static int chip_start(void)
{
    encif_reset();
    tlm.id = encif_read(ENCIF_R_ID);
    tlm.frames++;
    if (tlm.id != ENCIF_ID) {
        return 0;
    }
    encif_write(ENCIF_R_CTRL, 0x31);          /* 使能、不反向、Z 不清零、滤波长度 3 */
    tlm.ctrl = encif_read(ENCIF_R_CTRL);
    encif_write(ENCIF_R_STATUS, ENCIF_ST_ERR | ENCIF_ST_IVLD);
    tlm.frames += 3;
    for (int i = 0; i < WIN_MS; i++) {
        hist[i] = 0;
    }
    tlm.idx_valid = 0;
    tlm.abs_cnt = -1;
    return 1;
}

static void sample(uint32_t now)
{
    int32_t c = (int32_t)encif_read(ENCIF_R_CNT);
    uint32_t st = encif_read(ENCIF_R_STATUS);
    tlm.frames += 2;
    tlm.cnt = c;
    tlm.status = st;
    tlm.turns = div_cpr(c);
    tlm.angle_cnt = mod_cpr(c);

    int k = (int)(now % WIN_MS);
    if (now >= WIN_MS) {
        tlm.rpm_x10 = (c - hist[k]) * 6;      /* 计数/10 ms → rpm×10：d / CPR / 0.01 s × 60 × 10 = d × 6 */
    }
    hist[k] = c;

    if (st & ENCIF_ST_IVLD) {                 /* 过了 Z：取锁存值，清标志等下一次 */
        tlm.idx = (int32_t)encif_read(ENCIF_R_IDX);
        tlm.idx_valid = 1;
        encif_write(ENCIF_R_STATUS, ENCIF_ST_IVLD);
        tlm.frames += 2;
    }
    if (tlm.idx_valid) {
        tlm.abs_cnt = mod_cpr(c - tlm.idx);
    }
    if (st & ENCIF_ST_ERR) {                  /* A/B 同时跳：丢步风险，记一次并清除 */
        tlm.err_count++;
        encif_write(ENCIF_R_STATUS, ENCIF_ST_ERR);
        tlm.frames++;
    }
}

int main(void)
{
    tlm.magic = 0x314D4C54u;
    tlm.state = ST_BOOT;
    tlm.abs_cnt = -1;

    SYST_RVR = SYSCLK_HZ / 1000u - 1u;        /* 1 kHz */
    SYST_CVR = 0;
    SYST_CSR = 7;                             /* 处理器时钟、开中断、使能 */

    encif_init_bus();
    tlm.state = chip_start() ? ST_RUN : ST_MISSING;

    uint32_t last = ticks;
    for (;;) {
        while (ticks == last) {
            __asm volatile("wfi");
        }
        last = ticks;
        tlm.tick_ms = last;
        if (tlm.state == ST_RUN) {
            sample(last);
        } else if (last % RETRY_MS == 0) {
            tlm.retries++;
            if (chip_start()) {
                tlm.state = ST_RUN;
            }
        }
    }
}

/* WQ-ENCIF 驱动。引脚（第 98 轮 B 版原理图）：PA4 片选（软件控制）、PA5 SCK、PA6 MISO、PA7 MOSI（AF5 = SPI1），PB1 芯片复位。 */
#include "encif.h"
#include "regs.h"

static void delay_cycles(volatile uint32_t n)
{
    while (n--) {
    }
}

void encif_init_bus(void)
{
    RCC_AHB2ENR |= RCC_GPIOAEN | RCC_GPIOBEN;
    RCC_APB2ENR |= RCC_SPI1EN;

    /* PA4 推挽输出（片选，先拉高）；PA5/6/7 复用 AF5（STM32G431 数据手册 DS12589 复用功能表：PA5/PA6/PA7 的 SPI1 为 AF5） */
    GPIO_BSRR(GPIOA_BASE) = 1u << 4;
    GPIO_MODER(GPIOA_BASE) = (GPIO_MODER(GPIOA_BASE) & ~(0xFFu << 8)) | (1u << 8) | (2u << 10) | (2u << 12) | (2u << 14);
    GPIO_OSPEEDR(GPIOA_BASE) |= 0xFFu << 8;
    GPIO_AFRL(GPIOA_BASE) = (GPIO_AFRL(GPIOA_BASE) & ~(0xFFFu << 20)) | (5u << 20) | (5u << 24) | (5u << 28);
    /* PB1 推挽输出（芯片复位，低有效，先拉低） */
    GPIO_BSRR(GPIOB_BASE) = 1u << (16 + 1);
    GPIO_MODER(GPIOB_BASE) = (GPIO_MODER(GPIOB_BASE) & ~(3u << 2)) | (1u << 2);

    /* SPI1：主机、模式 0（CPOL=0 CPHA=0）、16 MHz/4 = 4 MHz（芯片要求 SCLK ≤ 50 MHz/10）、软件片选、8 位 */
    SPI1_CR1 = SPI_CR1_MSTR | SPI_CR1_BR_DIV4 | SPI_CR1_SSM | SPI_CR1_SSI;
    SPI1_CR2 = SPI_CR2_DS_8BIT | SPI_CR2_FRXTH;
    SPI1_CR1 |= SPI_CR1_SPE;
}

void encif_reset(void)
{
    GPIO_BSRR(GPIOB_BASE) = 1u << (16 + 1);
    delay_cycles(100);
    GPIO_BSRR(GPIOB_BASE) = 1u << 1;
    delay_cycles(100);  /* 芯片同步器与上电对齐要几拍（50 MHz 下 < 1 µs） */
}

static uint8_t xfer(uint8_t b)
{
    while (!(SPI1_SR & SPI_SR_TXE)) {
    }
    SPI1_DR8 = b;
    while (!(SPI1_SR & SPI_SR_RXNE)) {
    }
    return SPI1_DR8;
}

static uint32_t frame(uint8_t cmd, uint32_t data)
{
    uint32_t r = 0;
    GPIO_BSRR(GPIOA_BASE) = 1u << (16 + 4);   /* 片选拉低 */
    xfer(cmd);
    for (int i = 3; i >= 0; i--) {
        r = (r << 8) | xfer((uint8_t)(data >> (8 * i)));
    }
    while (SPI1_SR & SPI_SR_BSY) {
    }
    GPIO_BSRR(GPIOA_BASE) = 1u << 4;          /* 片选拉高：一帧结束 */
    return r;
}

uint32_t encif_read(uint8_t addr) { return frame(addr & 0x7F, 0); }

void encif_write(uint8_t addr, uint32_t data) { (void)frame(0x80 | (addr & 0x7F), data); }

/* WQ-ENCIF 驱动：40 位一帧（8 位命令 + 32 位数据，高位先出），SPI 模式 0。寄存器见第 92 轮规格。 */
#ifndef ENCIF_H
#define ENCIF_H
#include <stdint.h>

#define ENCIF_ID 0x454E4331u      /* "ENC1" */
#define ENCIF_R_ID 0
#define ENCIF_R_CTRL 1            /* 位 0 使能、1 反向、2 Z 清零、4–7 滤波长度 */
#define ENCIF_R_STATUS 2          /* 位 0 方向、1 错误、2 Z 已锁存；写 1 清位 1、位 2 */
#define ENCIF_R_CNT 3
#define ENCIF_R_IDX 4
#define ENCIF_ST_ERR (1u << 1)
#define ENCIF_ST_IVLD (1u << 2)

void encif_init_bus(void);
void encif_reset(void);
uint32_t encif_read(uint8_t addr);
void encif_write(uint8_t addr, uint32_t data);

#endif

/* 启动代码：向量表、复制 .data、清零 .bss、进 main。 */
#include <stdint.h>

extern uint32_t _estack, _sidata, _sdata, _edata, _sbss, _ebss;
int main(void);
void SysTick_Handler(void);

void Reset_Handler(void)
{
    uint32_t *s = &_sidata, *d = &_sdata;
    while (d < &_edata) {
        *d++ = *s++;
    }
    for (d = &_sbss; d < &_ebss;) {
        *d++ = 0;
    }
    main();
    for (;;) {
    }
}

void Default_Handler(void)
{
    for (;;) {
    }
}

__attribute__((section(".isr_vector"), used)) const void *const vectors[16] = {
    &_estack, Reset_Handler, Default_Handler, Default_Handler,   /* SP、复位、NMI、HardFault */
    Default_Handler, Default_Handler, Default_Handler, 0, 0, 0, 0,
    Default_Handler, Default_Handler, 0, Default_Handler,        /* SVC、调试、保留、PendSV */
    SysTick_Handler,
};

/* STM32G431CB：128 KB Flash，SRAM1 + SRAM2 共 22 KB（RM0440 存储器映射） */
MEMORY
{
  FLASH (rx) : ORIGIN = 0x08000000, LENGTH = 128K
  RAM (rwx) : ORIGIN = 0x20000000, LENGTH = 22K
}
_estack = ORIGIN(RAM) + LENGTH(RAM);
SECTIONS
{
  .text : { KEEP(*(.isr_vector)) *(.text*) *(.rodata*) . = ALIGN(4); } > FLASH
  _sidata = LOADADDR(.data);
  .data : { _sdata = .; *(.data*) . = ALIGN(4); _edata = .; } > RAM AT > FLASH
  .bss (NOLOAD) : { _sbss = .; *(.bss*) *(COMMON) . = ALIGN(4); _ebss = .; } > RAM
}

// STM32G431CB 仿真平台（Renode）——只描述本轮固件用到的部分。地址按 RM0440《STM32G4 参考手册》的存储器映射。
// 第 100 轮：驱动板 B 版固件仿真。示例，非 ST 官方平台文件。
cpu: CPU.CortexM @ sysbus
    cpuType: "cortex-m4f"
    nvic: nvic

// NVIC 与 SysTick；上电后系统时钟为 HSI16（RM0440 RCC 章），SysTick 按 16 MHz 计
nvic: IRQControllers.NVIC @ sysbus 0xE000E000
    systickFrequency: 16000000
    -> cpu@0

// 128 KB Flash（RM0440 存储器映射：0x0800 0000），SRAM1 16 KB + SRAM2 6 KB 连续（0x2000 0000，共 22 KB）
flash: Memory.MappedMemory @ sysbus 0x08000000
    size: 0x20000

sram: Memory.MappedMemory @ sysbus 0x20000000
    size: 0x5800

// GPIOA/GPIOB（AHB2，RM0440 存储器映射：0x4800 0000 / 0x4800 0400）
gpioPortA: GPIOPort.STM32_GPIOPort @ sysbus <0x48000000, +0x400>

gpioPortB: GPIOPort.STM32_GPIOPort @ sysbus <0x48000400, +0x400>

// SPI1（APB2，RM0440 存储器映射：0x4001 3000）
spi1: SPI.STM32SPI @ sysbus 0x40013000

// RCC（0x4002 1000）只占位成一块可读写的存储：固件只写时钟使能位，不等就绪标志
rcc: Memory.MappedMemory @ sysbus 0x40021000
    size: 0x400

// WQ-ENCIF 寄存器级模型 + 虚拟电机（Renode 外设，挂在 spi1 上）。第 100 轮：驱动板 B 版固件仿真。
// 规则同第 92 轮规格（factory/designs/wq-encif/rtl/wq_encif.v 文件头、model/encif.py）：
//   一帧 40 位 = 8 位命令（位 7：1 写 0 读；低 7 位地址）+ 32 位数据，高位先出；读在命令字节收完时取快照；写在第 40 位生效。
//   寄存器 0 ID "ENC1"；1 CTRL（位 0 使能、1 反向、2 Z 清零、4–7 滤波）；2 STATUS（位 0 方向、1 错误、2 Z 已锁存、3–5 A/B/Z 电平；
//   写 1 清位 1、位 2）；3 CNT（可写）；4 IDX（Z 上升沿时的计数）。
// 芯片 RTL 已在第 92/93 轮与 Python 模型逐拍比对；这里只做寄存器级，跑得快。示例，芯片未流片。
//
// 虚拟电机：转速曲线（时刻 s : 转速 rpm，分段线性）积分成位置（计数，2500 线 ×4 = 10000 计数/转）；
// Z 在绝对位置为 10000 的整数倍处；芯片计数 = 复位释放后走过的计数。
using System;
using System.Collections.Generic;
using System.Globalization;
using Antmicro.Renode.Core;
using Antmicro.Renode.Logging;
using Antmicro.Renode.Peripherals.SPI;

namespace Antmicro.Renode.Peripherals.SPI
{
    public class WqEncif : ISPIPeripheral, IGPIOReceiver
    {
        public const int CPR = 10000;
        public const uint ID = 0x454E4331;

        public WqEncif(IMachine machine)
        {
            this.machine = machine;
            prof = new List<double[]> { new double[] { 0, 0 } };
            Reset();
        }

        // ---------------------------------------------------------------- 监视器命令（仿真脚本用）
        // 转速曲线，如 "0:0,0.1:600,0.5:600"
        public void Profile(string spec)
        {
            var l = new List<double[]>();
            foreach(var seg in spec.Split(','))
            {
                var kv = seg.Split(':');
                l.Add(new double[] { double.Parse(kv[0], CultureInfo.InvariantCulture), double.Parse(kv[1], CultureInfo.InvariantCulture) });
            }
            prof = l;
        }

        public void StartPos(int counts) { pos0 = counts; plast = Floor(PosAt(Now())); }
        public void InjectError() { Update(); err = 1; errInjected++; }
        public void Absent(bool v) { absent = v; }
        public string Truth()
        {
            var t = Now();
            var p = PosAt(t);
            return string.Format(CultureInfo.InvariantCulture, "T {0:F6} {1:F3} {2:F3} {3} {4}", t, p - pos0, RpmAt(t), Floor(p), relBase);
        }

        // ---------------------------------------------------------------- SPI
        public byte Transmit(byte b)
        {
            if(absent || !selected || !rstn)
            {
                return 0;
            }
            byte ret = 0;
            if(nbyte == 0)
            {
                cmd = b;
                if((cmd & 0x80) == 0)
                {
                    Update();
                    snap = Reg(cmd & 0x7F);
                }
            }
            else if(nbyte <= 4)
            {
                if((cmd & 0x80) == 0)
                {
                    ret = (byte)(snap >> (8 * (4 - nbyte)));
                }
                else
                {
                    wdata = (wdata << 8) | b;
                    if(nbyte == 4)
                    {
                        Update();
                        Write(cmd & 0x7F, wdata);
                    }
                }
            }
            nbyte++;
            frames += nbyte == 5 ? 1 : 0;
            return ret;
        }

        public void FinishTransmission() { }

        // GPIO 0：片选（低有效，PA4）；GPIO 1：复位（低有效，PB1）
        public void OnGPIO(int number, bool value)
        {
            if(number == 0)
            {
                selected = !value;
                nbyte = 0;
                wdata = 0;
            }
            else if(number == 1)
            {
                if(!value)
                {
                    ResetRegs();
                }
                else if(!rstn)
                {
                    plast = Floor(PosAt(Now()));
                    relBase = plast;
                }
                rstn = value;
            }
        }

        public void Reset()
        {
            ResetRegs();
            selected = false;
            rstn = true;
            nbyte = 0;
            plast = Floor(PosAt(Now()));
            relBase = plast;
        }

        public int Frames => frames;

        // ---------------------------------------------------------------- 寄存器
        private void ResetRegs()
        {
            en = 1; inv = 0; zclr = 0; flen = 3;
            dir = 1; err = 0; ivld = 0;
            cnt = 0; idx = 0;
        }

        private uint Reg(int a)
        {
            switch(a)
            {
            case 0: return ID;
            case 1: return (uint)(en | inv << 1 | zclr << 2 | flen << 4);
            case 2:
                var ph = ((plast % 4) + 4) % 4;               // 正交相位 0..3：A 领先 B
                int ra = (ph == 1 || ph == 2) ? 1 : 0, rb = (ph == 2 || ph == 3) ? 1 : 0;
                int rz = (((plast % CPR) + CPR) % CPR) == 0 ? 1 : 0;
                return (uint)(dir | err << 1 | ivld << 2 | ra << 3 | rb << 4 | rz << 5);
            case 3: return cnt;
            case 4: return idx;
            default: return 0;
            }
        }

        private void Write(int a, uint v)
        {
            if(a == 1) { en = (int)(v & 1); inv = (int)(v >> 1 & 1); zclr = (int)(v >> 2 & 1); flen = (int)(v >> 4 & 0xF); }
            else if(a == 2) { if((v & 2) != 0) err = 0; if((v & 4) != 0) ivld = 0; }
            else if(a == 3) { cnt = v; }
        }

        // 把虚拟电机推进到当前时刻：逐个处理途中的 Z
        private void Update()
        {
            if(!rstn)
            {
                return;
            }
            long p = Floor(PosAt(Now()));
            while(p != plast)
            {
                int s = p > plast ? 1 : -1;
                // 下一个 Z（10000 的整数倍）：正转取 (plast, p]，反转取 [p, plast)
                long z = s > 0 ? FloorDiv(plast, CPR) * CPR + CPR : FloorDiv(plast - 1, CPR) * CPR;
                bool hit = s > 0 ? z <= p : z >= p;
                long to = hit ? z : p;
                Step(to - plast, s);
                plast = to;
                if(hit)
                {
                    idx = cnt; ivld = 1;
                    if(zclr == 1 && en == 1)
                    {
                        cnt = 0;
                    }
                }
            }
        }

        private void Step(long d, int s)
        {
            if(d == 0 || en == 0)
            {
                return;
            }
            cnt = (uint)(cnt + (inv == 1 ? -d : d));
            dir = (s > 0) ^ (inv == 1) ? 1 : 0;
        }

        // ---------------------------------------------------------------- 虚拟电机
        private double Now() { return machine.LocalTimeSource.ElapsedVirtualTime.TotalSeconds; }

        private double RpmAt(double t)
        {
            if(t <= prof[0][0]) return prof[0][1];
            for(int i = 1; i < prof.Count; i++)
            {
                if(t <= prof[i][0])
                {
                    var a = prof[i - 1]; var b = prof[i];
                    return a[1] + (b[1] - a[1]) * (t - a[0]) / (b[0] - a[0]);
                }
            }
            return prof[prof.Count - 1][1];
        }

        // 绝对位置（计数）= 起始位置 + ∫ rpm/60·CPR dt（分段线性，梯形精确积分）
        private double PosAt(double t)
        {
            double acc = 0, k = CPR / 60.0;
            double t0 = 0, r0 = RpmAt(0);
            var pts = new List<double>();
            foreach(var q in prof) if(q[0] > 0 && q[0] < t) pts.Add(q[0]);
            pts.Add(t);
            foreach(var t1 in pts)
            {
                var r1 = RpmAt(t1);
                acc += (r0 + r1) / 2 * (t1 - t0) * k;
                t0 = t1; r0 = r1;
            }
            return pos0 + acc;
        }

        private static long Floor(double x) { return (long)Math.Floor(x + 1e-9); }
        private static long FloorDiv(long a, long b) { return (long)Math.Floor((double)a / b); }

        private readonly IMachine machine;
        private List<double[]> prof;
        private double pos0;
        private long plast, relBase;
        private bool selected, rstn, absent;
        private int nbyte, frames, errInjected;
        private byte cmd;
        private uint snap, wdata, cnt, idx;
        private int en, inv, zclr, flen, dir, err, ivld;
    }
}
